// Style-image ids for the Browse map's SymbolLayers. The images themselves are
// static PNGs bundled with the app (see pinIconAssets.js, generated by
// scripts/generate-pin-icons.js), so they are available on the first render and
// nothing has to be rasterized on the device.
// Ratings are bucketed to the nearest RATING_STEP so a fixed, small set of
// icons covers every continuous rating value.
export { PIN_ICON_IMAGES } from "./pinIconAssets";

// Keep in sync with RATING_STEP, PAD_TOP and the ids in
// scripts/generate-pin-icons.js.
const RATING_STEP = 0.25;
// Height of the image canvas above the pin's tip, and of the pin's top within
// it, in points.
const PIN_CANVAS_HEIGHT = 44;
const PIN_TOP = 2;

// Web's rules: grey when unavailable (and then never the suggested badge).
function look(unavailable, suggested) {
  if (unavailable) return "unavailable";
  return suggested ? "suggested" : "available";
}

export function pinIconId(rating, unavailable, suggested) {
  const bucket =
    rating == null || rating <= 0 ? "none" : (Math.round(Math.min(rating, 5) / RATING_STEP) * RATING_STEP).toFixed(2);
  return `pin-${bucket}-${look(unavailable, suggested)}`;
}

export function clusterIconId(unavailable, suggested) {
  return `cluster-${look(unavailable, suggested)}`;
}

// A group pin's count is centred where web draws it, 17.75pt below the pin's
// top, so this far above the tip at full size.
const COUNT_CENTER = PIN_CANVAS_HEIGHT - PIN_TOP - 17.75;

// One pin (see buildPins in BrowseMapView) as a GeoJSON feature for the pin
// layers. `motion` is the in-between state of an animating pin: its opacity,
// a size multiplier and a screen offset (ox, oy) in points.
export function pinFeature(pin, { opacity = 1, scale = 1, ox = 0, oy = 0 } = {}) {
  const size = pin.size * scale;
  const textSize = pin.textSize * scale;
  const x = pin.dx + ox;
  return {
    type: "Feature",
    geometry: { type: "Point", coordinates: [pin.lng, pin.lat] },
    properties: {
      listingId: pin.isCluster ? null : pin.members[0]._id,
      isCluster: pin.isCluster,
      dx: pin.dx,
      size,
      iconId: pin.iconId,
      // Mapbox scales icon and text offsets by the icon and text size.
      offset: [x / size, oy / size],
      label: pin.label,
      textSize,
      textOffset: [x / textSize, (oy - COUNT_CENTER * size) / textSize],
      sortKey: pin.sortKey,
      opacity,
    },
  };
}

// Style shared by the static and the animating pin layers. The anchor is the
// pin's tip, so scaling (the selected pin, the motion) keeps it on its spot.
export const PIN_LAYER_STYLE = {
  iconImage: ["get", "iconId"],
  iconAnchor: "bottom",
  iconAllowOverlap: true,
  iconIgnorePlacement: true,
  iconSize: ["get", "size"],
  iconOffset: ["get", "offset"],
  iconOpacity: ["get", "opacity"],
  symbolSortKey: ["get", "sortKey"],
  textField: ["get", "label"],
  textFont: ["DIN Offc Pro Bold", "Arial Unicode MS Bold"],
  textSize: ["get", "textSize"],
  textOffset: ["get", "textOffset"],
  textColor: "#FFFFFF",
  textOpacity: ["get", "opacity"],
  textAllowOverlap: true,
  textIgnorePlacement: true,
};
